insert into public.farms (id,name,cluster,location,region,bio,practices,certifications,photo,farmer_name,farmer_photo,rating,reviews_count,established_year,phone,lat,lng) values ('farm-ejisu','Ejisu Agro-Green Cooperative','Kumasi East Farm Cluster','Ejisu Agro Belt, Ashanti Region','Kumasi Metro Area (22km from CBD)','Pioneering regenerative peri-urban farming for over 14 years. We supply Kumasi urban households with pesticide-free leafy greens and premium sweet Roma tomatoes picked fresh at dawn.',array['Drip irrigation using clean borehole water','Zero synthetic chemical pesticides','Sun-cured organic compost fertilization','Harvested strictly under 6 hours before delivery']::text[],'[{"id":"cert-1","label":"MoFA Verified Farm","issuer":"Ministry of Food and Agriculture, Ghana","icon":"ShieldCheck","verifiedDate":"2026 Season"},{"id":"cert-2","label":"Eco-Certified Soil","issuer":"Ghana Organic Agriculture Network","icon":"Leaf","verifiedDate":"Active"},{"id":"cert-3","label":"Cold-Chain Compliant","issuer":"AgriCom+ Food Safety Audit","icon":"Award","verifiedDate":"Passed Grade A"}]'::jsonb,'https://images.unsplash.com/photo-1500937386664-56d1dfef3854?auto=format&fit=crop&w=1000&q=80','Kwame Mensah & Sons','https://images.unsplash.com/photo-1544717305-2782549b5136?auto=format&fit=crop&w=600&q=80',4.9,184,2012,'+233 24 412 8990',6.7167,-1.5) on conflict (id) do nothing;
insert into public.farms (id,name,cluster,location,region,bio,practices,certifications,photo,farmer_name,farmer_photo,rating,reviews_count,established_year,phone,lat,lng) values ('farm-mampong','Mampong Highland Organic Farmers','Ashanti Ridge Highlands Cluster','Mampong Scarp, Ashanti Region','Highland Ridge (50km north of Kumasi)','Perched in the cooler mist-covered heights of the Mampong ridge. The volcanic loam and altitude produce exceptionally sweet ginger, crisp garden eggs, and nutritious mountain cocoyam leaves.',array['Terraced contour farming to prevent erosion','Natural companion planting against insect pests','Rainwater harvesting and natural mountain springs']::text[],'[{"id":"cert-4","label":"Certified Pesticide-Free","issuer":"Ashanti Regional Farmers Alliance","icon":"ShieldCheck","verifiedDate":"2026"},{"id":"cert-5","label":"Fair Trade Certified","issuer":"Ghana Fair Produce Collective","icon":"Award","verifiedDate":"Verified"}]'::jsonb,'https://images.unsplash.com/photo-1592982537447-6f2a6a0c5c1c?auto=format&fit=crop&w=1000&q=80','Maame Akosua Serwaa','https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=600&q=80',4.8,142,2016,'+233 50 891 3244',7.06,-1.4) on conflict (id) do nothing;
insert into public.farms (id,name,cluster,location,region,bio,practices,certifications,photo,farmer_name,farmer_photo,rating,reviews_count,established_year,phone,lat,lng) values ('farm-offinso','Offinso Valley Tubers & Plantains','Offin River Basin Cooperative','Offinso South Agro Zone, Ashanti','Offinso Valley (28km north of Kumasi)','Renowned throughout Ghana as the yam and plantain heartland. We dig fresh Pona yams and harvest robust Apem plantains only when fully mature on the tree.',array['Traditional mounding with dry-grass mulching','Zero chemical wax or surface preservatives on tubers','Field-side inspection and prompt grading']::text[],'[{"id":"cert-6","label":"MoFA Root Crop Grade A","issuer":"Ghana Standards Authority & MoFA","icon":"CheckCircle","verifiedDate":"2026"},{"id":"cert-7","label":"100% Traceable Harvest","issuer":"AgriCom+ Digital Registry","icon":"QrCode","verifiedDate":"Tracked"}]'::jsonb,'https://images.unsplash.com/photo-1589923188900-85dae523342b?auto=format&fit=crop&w=1000&q=80','Opanin Kofi Boakye','https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=600&q=80',4.95,230,2008,'+233 20 774 1928',6.9042,-1.6575) on conflict (id) do nothing;
insert into public.farms (id,name,cluster,location,region,bio,practices,certifications,photo,farmer_name,farmer_photo,rating,reviews_count,established_year,phone,lat,lng) values ('farm-barekese','Barekese Basin Fresh Orchards','Atwima Nwabiagya Green Cluster','Barekese Catchment, Ashanti','North-West Kumasi Peri-Urban (18km)','Located along the pristine Barekese water reservoir basin. We specialize in tree-ripened Ashanti sweet pawpaws, golden pineapples, and cold-pressed pure artisanal red palm oil.',array['Zero synthetic ripening agents or calcium carbide','Artisanal wooden press oil extraction','Biological pest control through flowering borders']::text[],'[{"id":"cert-8","label":"Unrefined Pure Grade","issuer":"FDA Ghana Tested","icon":"ShieldCheck","verifiedDate":"2026"},{"id":"cert-9","label":"Zero Carbide Guarantee","issuer":"Kumasi Safe Food Taskforce","icon":"CheckCircle","verifiedDate":"Guaranteed"}]'::jsonb,'https://images.unsplash.com/photo-1615811361523-6bd03d7748e7?auto=format&fit=crop&w=1000&q=80','Yaw Adjei Frimpong','https://images.unsplash.com/photo-1500648767791-00dcc994a43e?auto=format&fit=crop&w=600&q=80',4.7,98,2018,'+233 24 330 1199',6.84,-1.72) on conflict (id) do nothing;
insert into public.products (id,name,local_name,category,price,original_price,discount_percent,unit,weight,images,farm_id,description,health_tags,in_stock,stock_count,harvest_date,shelf_life,nutrition_highlights) values ('prod-yam-pona','Fresh Pona Yam (White Tuber Pack)','Bayere Pona','tubers',65,85,23,'Bundle (3 medium tubers)','~5.5 kg',array['https://images.unsplash.com/photo-1596040033229-a9821ebd058d?auto=format&fit=crop&w=800&q=80','https://images.unsplash.com/photo-1589923188900-85dae523342b?auto=format&fit=crop&w=800&q=80']::text[],'farm-offinso','Crisp, powdery white Pona yams freshly harvested in Offinso South. Flavourful and dry-textured, perfect for boiling with garden egg stew, frying yam chips, or pounding into authentic fufu without bitterness.',array['Farm Direct','No Chemical Wax','Rich in Potassium']::text[],true,42,'Yesterday at 05:30 AM','3–4 weeks in cool airy spot',array['High fiber','Complex carbs','Naturally gluten-free']::text[]) on conflict (id) do nothing;
